/* @autogenerated */
import type { ContextValue } from '@shared/context/state/app-state.service';

/** Una referencia de la entidad: a qué entidad apunta y con qué filtro múltiple (`in`) se filtra por ella. */
export interface ReferenceMetadata {
  entity: string;
  filter?: string;
}

/** Referencias y campo por defecto de cada entidad referenciada, tal como los genera el modelo. */
export interface ContextReferences {
  /** Campos de referencia de la entidad, por nombre de campo. */
  references?: { [field: string]: ReferenceMetadata };
  /** Campo que recibe el contexto de una entidad cuando varios campos la referencian (`context-default`). */
  contextFields?: { [entity: string]: string };
}

/** Una entrada del contexto aplicada a un campo de la entidad. */
export interface ContextBinding {
  /** Clave de la entrada en el contexto. */
  key: string;
  field: string;
  /** Filtro múltiple del campo; sin él la entrada no puede filtrar los listados. */
  filter?: string;
  /** Claves referenciadas (sin `$ref`); vacío si la entrada no tiene valor. */
  values: string[];
  fixed: boolean;
  toFilter: boolean;
}

/** Lo que el contexto hace con los campos de una entidad, para los formularios y la importación. */
export interface ContextFields {
  /** Campos que impone el contexto (`ContextValue.fixed`), con su valor: no se pueden cambiar. */
  fixed: Record<string, { $ref: string }>;
  /** Campos que el contexto rellena si vienen vacíos (`ContextValue.default`). */
  defaults: Record<string, { $ref: string }>;
  /** Campos y filtros múltiples por los que el contexto ya acota los listados: sobran en la búsqueda. */
  filtered: string[];
}

/** {@link ContextFields} de unas entradas ya aplicadas a la entidad. */
export function contextFields(bindings: ContextBinding[]): ContextFields {
  const result: ContextFields = { fixed: {}, defaults: {}, filtered: [] };
  bindings.forEach((binding) => {
    if (binding.fixed && binding.values.length === 1) {
      (binding.toFilter ? result.fixed : result.defaults)[binding.field] = { $ref: binding.values[0] };
    }
    if (binding.toFilter && binding.values.length) {
      result.filtered.push(binding.field, ...(binding.filter ? [binding.filter] : []));
    }
  });
  return result;
}

/**
 * Campo de la entidad que recibe cada entrada del contexto. Con `entity`, el campo cuya referencia apunta a esa
 * entidad: si hay varios, el de `contextFields` o, en su defecto, el que se llama como la clave; si sigue habiendo
 * duda la entrada no se aplica. Sin `entity`, el campo de referencia con el nombre de la clave.
 */
export function contextBindings(
  meta: ContextReferences,
  contexts: Record<string, ContextValue | null>,
): ContextBinding[] {
  const references = meta.references ?? {};
  const bindings: ContextBinding[] = [];
  Object.entries(contexts).forEach(([key, ctx]) => {
    if (!ctx) {
      return;
    }
    const field = ctx.entity ? fieldFor(meta, ctx.entity, key) : references[key] ? key : undefined;
    if (field) {
      bindings.push({
        key,
        field,
        filter: references[field].filter,
        values: refs(ctx.value),
        fixed: ctx.fixed,
        toFilter: ctx.toFilter,
      });
    }
  });
  return bindings;
}

/**
 * La consulta acotada por el contexto: cada entrada de filtrado se lleva al filtro múltiple de su campo,
 * intersecada con lo que la consulta ya pida por ese campo. `null` si la intersección queda vacía (no hay resultados).
 */
export function scopeQuery<F>(query: F, bindings: ContextBinding[]): F | null {
  let scoped = query as any;
  for (const binding of bindings) {
    if (!binding.toFilter || !binding.filter || !binding.values.length) {
      continue;
    }
    let allowed = binding.values;
    [scoped[binding.field], scoped[binding.filter]].forEach((explicit) => {
      if (present(explicit)) {
        const wanted = refs(explicit);
        allowed = allowed.filter((value) => wanted.includes(value));
      }
    });
    if (!allowed.length) {
      return null;
    }
    scoped = { ...scoped, [binding.filter]: allowed };
    delete scoped[binding.field];
  }
  return scoped as F;
}

/**
 * El elemento con los valores fijos del contexto en sus campos: `ContextValue.fixed` los impone,
 * `ContextValue.default` solo rellena los vacíos. Las entradas con varios valores no se inyectan.
 */
export function injectContext<T>(item: T, bindings: ContextBinding[]): T {
  const fixed = bindings.filter((binding) => binding.fixed && binding.values.length === 1);
  if (!fixed.length || !item || typeof item !== 'object') {
    return item;
  }
  const copy = { ...item } as any;
  fixed.forEach((binding) => {
    if (binding.toFilter || !present(copy[binding.field])) {
      copy[binding.field] = { $ref: binding.values[0] };
    }
  });
  return copy;
}

function fieldFor(meta: ContextReferences, entity: string, key: string): string | undefined {
  const references = meta.references ?? {};
  const candidates = Object.keys(references).filter((field) => references[field].entity === entity);
  const preferred = meta.contextFields?.[entity];
  if (preferred && candidates.includes(preferred)) {
    return preferred;
  }
  if (candidates.length === 1) {
    return candidates[0];
  }
  return candidates.find((field) => field === key);
}

/** Claves de un valor de referencia: uno o varios, como `{ $ref }` o como clave. */
function refs(value: unknown): string[] {
  const list = Array.isArray(value) ? value : [value];
  return list
    .map((item) => (item && typeof item === 'object' && '$ref' in item ? (item as { $ref: unknown }).$ref : item))
    .filter(present)
    .map((item) => String(item));
}

function present(value: unknown): boolean {
  return value !== undefined && value !== null && value !== '' && !(Array.isArray(value) && !value.length);
}
